import os
import random
import string
from typing import List

# Target data type: filename/path string
# Used by FUZZ_PARAM_FILENAME in stubs for preprocessor append_file/append_string/add_include_path.
# We generate plausible, varied paths with directories and filenames, sometimes nested, with
# different separators and extensions typical for shader/effect sources. We keep total size <= 4096.

_EXTS = [
    ".fx", ".fxh", ".hlsl", ".glsl", ".shader", ".txt", ".inc", ".h", ".c", ".cpp",
    "",  # no extension
]

_COMPONENTS = list(string.ascii_letters + string.digits + "-_ .")

# Some interesting directory names often seen in shader repositories
_DIR_NAMES = [
    "shaders", "include", "effects", "data", "src", "res", "assets",
    "..", ".", "third_party", "external", "common", "lib",
]

# Root candidates: empty (relative), current dir, Unix root, Windows drive roots
_ROOTS = ["", ".", "/", "C:/", "D:/", "E:/", "C:\\", "D:\\"]

# Path separators choices
_SEP_CHOICES = ["/", "\\"]

# Filenames that look like real shader or header names
_BASENAMES = [
    "main", "postprocess", "tonemap", "fxaa", "smaa", "bloom", "blur",
    "color_grade", "lut", "compute", "vertex", "pixel", "common", "util",
]

# Add some macro-like include names without directories
_HEADER_LIKE = [
    "config.h", "version.inc", "platform.h", "intrinsics.h", "math.inc", "types.h"
]


def _rand_name(rng: random.Random, min_len: int = 3, max_len: int = 12) -> str:
    n = rng.randint(min_len, max_len)
    # Avoid trailing spaces and dots which Windows dislikes; trim later
    s = ''.join(rng.choice(_COMPONENTS) for _ in range(n)).strip(" .")
    if not s:
        s = "x"
    return s


def _rand_dir_component(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(_DIR_NAMES)
    return _rand_name(rng)


def _rand_basename(rng: random.Random) -> str:
    if rng.random() < 0.6:
        base = rng.choice(_BASENAMES)
    elif rng.random() < 0.5:
        base = _rand_name(rng)
    else:
        base = rng.choice(_HEADER_LIKE).rsplit('.', 1)[0]
    # Occasionally add numeric suffix
    if rng.random() < 0.4:
        base += str(rng.randint(0, 999))
    return base


def _rand_extension(rng: random.Random) -> str:
    if rng.random() < 0.85:
        return rng.choice(_EXTS)
    # Rare custom extension
    return "." + _rand_name(rng, 2, 4).lower()


def _assemble_path(rng: random.Random) -> str:
    sep = rng.choice(_SEP_CHOICES)
    root = rng.choice(_ROOTS)

    # Normalize root separators
    path_parts: List[str] = []
    if root:
        # Convert root to chosen separator style
        root_norm = root.replace('/', sep).replace('\\', sep)
        # Ensure root ends with separator if it is a root-like spec
        if root_norm in {sep, f"C:{sep}", f"D:{sep}", f"E:{sep}"}:
            path = root_norm
        else:
            path = root_norm
    else:
        path = ""

    # Depth from 0 to 5
    depth = rng.randint(0, 5)
    for _ in range(depth):
        comp = _rand_dir_component(rng)
        # Avoid empty components
        if not comp:
            comp = "dir"
        path_parts.append(comp)

    # Choose a basename
    base = _rand_basename(rng)
    ext = _rand_extension(rng)
    filename = base + ext

    # Occasionally pick header-like include without directories
    if rng.random() < 0.15:
        filename = rng.choice(_HEADER_LIKE)
        path_parts = []

    # Build full path
    middle = sep.join(p for p in path_parts if p)
    if path and not path.endswith(sep) and middle:
        path += sep
    if middle:
        path += middle
    if path and not path.endswith(sep):
        path += sep
    path += filename

    # Sometimes add relative traversals at start
    if rng.random() < 0.1 and not path.startswith(sep):
        prefix = sep.join([".."] * rng.randint(1, 3))
        path = prefix + sep + path

    # Constrain length
    if len(path) > 512:
        path = path[:512]

    return path


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose among a few themed generators for coverage
    mode = rng.random()
    if mode < 0.20:
        # Simple relative file in current directory
        name = _rand_basename(rng) + _rand_extension(rng)
        path = name
    elif mode < 0.40:
        # Deep Unix-like path
        path = "/" + "/".join(_rand_dir_component(rng) for _ in range(rng.randint(1, 6)))
        path = path.rstrip("/") + "/" + _rand_basename(rng) + _rand_extension(rng)
    elif mode < 0.60:
        # Windows-like absolute path with backslashes
        drive = rng.choice(["C:", "D:", "E:"])
        comps = [_rand_dir_component(rng) for _ in range(rng.randint(1, 6))]
        path = drive + "\\" + "\\".join(comps) + "\\" + _rand_basename(rng) + _rand_extension(rng)
    elif mode < 0.80:
        # Header-like include name only
        path = rng.choice(_HEADER_LIKE)
    else:
        # Mixed separators and roots
        path = _assemble_path(rng)

    # Ensure final buffer under 4096
    if len(path) > 4096:
        path = path[:4096]

    return path.encode("utf-8", errors="ignore")

import random
import string
from typing import List

# This generator produces valid and interesting ASCII/UTF-8 strings that exercise
# the ReShadeFX lexer, token, expression constant strings, and preprocessor macro APIs.
# It focuses on creating realistic shader/preprocessor snippets and identifiers,
# since the fuzzer stubs consume FUZZ_PARAM_STR for:
#  - location::source (filename-like)
#  - preprocessor macro name sanitization and replacement_list
#  - token literal_as_string
#  - expression::reset_to_rvalue_constant(std::string)
# The outputs are valid textual inputs (not mutated/invalid), under 4096 bytes.

_MAX_LEN = 4000

def _rand_ident(r: random.Random, min_len=1, max_len=16) -> str:
    first = r.choice(string.ascii_letters + "_")
    rest_len = r.randint(min_len - 1, max_len - 1)
    rest_chars = string.ascii_letters + string.digits + "_"
    return first + "".join(r.choice(rest_chars) for _ in range(rest_len))

def _rand_number(r: random.Random) -> str:
    kinds = ["int", "uint", "float"]
    k = r.choice(kinds)
    if k == "int":
        return str(r.randint(-2**31, 2**31 - 1))
    if k == "uint":
        return str(r.randint(0, 2**32 - 1)) + "u"
    # float
    # Use both simple and scientific formats
    if r.random() < 0.5:
        return f"{r.uniform(-1e5, 1e5):.6f}"
    else:
        base = r.uniform(0.0001, 1e5)
        exp = r.randint(-30, 30)
        return f"{base:.6e}".replace("e+", "e").replace("e-0", "e-")

def _rand_string_literal(r: random.Random, max_len=64) -> str:
    # Produce a valid C-like string literal with common escapes
    length = r.randint(0, max_len)
    pool = string.ascii_letters + string.digits + string.punctuation + " "
    s = []
    for _ in range(length):
        ch = r.choice(pool)
        if ch == "\\":
            s.append(r.choice(["\\n", "\\t", "\\r", "\\\\", "\\\"", "\\0"]))
        elif ch == "\"":
            s.append("\\\"")
        else:
            s.append(ch)
    return '"' + "".join(s) + '"'

def _rand_comment(r: random.Random) -> str:
    if r.random() < 0.5:
        # single-line
        text = _rand_plain_text(r, r.randint(0, 40))
        return "// " + text + "\n"
    # multi-line, avoid closing sequence inside content by splitting
    parts = [
        _rand_plain_text(r, r.randint(0, 20)),
        _rand_plain_text(r, r.randint(0, 20)),
    ]
    inner = (parts[0] + " " + parts[1]).replace("*/", "* /")
    return "/* " + inner + " */"

def _rand_plain_text(r: random.Random, length: int) -> str:
    pool = string.ascii_letters + string.digits + " _-.,;:/+#@$%()[]{}"  # keep lexer-friendly
    return "".join(r.choice(pool) for _ in range(length))

def _rand_pp_define(r: random.Random) -> str:
    name = _rand_ident(r, 1, r.randint(3, 12))
    # Sometimes function-like with params
    if r.random() < 0.6:
        nparams = r.randint(0, 3)
        params = ", ".join(_rand_ident(r, 1, 8) for _ in range(nparams))
        head = f"#define {name}({params})"
    else:
        head = f"#define {name}"
    # Replacement: mix identifiers, numbers, strings, operators
    tokens: List[str] = []
    for _ in range(r.randint(1, 8)):
        choice = r.random()
        if choice < 0.25:
            tokens.append(_rand_ident(r, 1, 10))
        elif choice < 0.5:
            tokens.append(_rand_number(r))
        elif choice < 0.7:
            tokens.append(_rand_string_literal(r, 24))
        else:
            tokens.append(r.choice([
                "+", "-", "*", "/", "&&", "||", "!", "==", "!=", "<=", ">=", "<<", ">>", "|", "&", "^", ","
            ]))
    return head + " " + " ".join(tokens) + "\n"

def _rand_typedef_struct(r: random.Random) -> str:
    sname = _rand_ident(r, 3, 10)
    fields = []
    types = [
        "bool", "int", "uint", "float",
        "float2", "float3", "float4",
        "int2", "uint2"
    ]
    n = r.randint(1, 4)
    for _ in range(n):
        t = r.choice(types)
        fname = _rand_ident(r, 1, 12)
        fields.append(f"    {t} {fname};")
    return "struct " + sname + " {\n" + "\n".join(fields) + "\n};\n"

def _rand_variable_block(r: random.Random) -> str:
    # Uniform-like declarations to exercise identifiers and literals
    lines = []
    for _ in range(r.randint(1, 4)):
        t = r.choice(["bool", "int", "uint", "float", "float2", "float3", "float4", "string"])
        name = _rand_ident(r, 1, 12)
        if t == "string":
            init = _rand_string_literal(r, 40)
        elif t == "bool":
            init = r.choice(["true", "false"])
        else:
            init = _rand_number(r)
        if r.random() < 0.5:
            lines.append(f"{t} {name} = {init};")
        else:
            # array form
            alen = r.randint(1, 4)
            lines.append(f"{t} {name}[{alen}];")
    return "\n".join(lines) + "\n"

def _rand_function(r: random.Random) -> str:
    rtype = r.choice(["void", "float", "int", "uint", "bool"])
    fname = _rand_ident(r, 3, 12)
    # Parameters
    params = []
    for _ in range(r.randint(0, 3)):
        pt = r.choice(["float", "int", "uint", "bool", "float2", "float3"])  # common types
        pname = _rand_ident(r, 1, 10)
        params.append(f"{pt} {pname}")
    header = f"{rtype} {fname}({', '.join(params)})"
    # Body with a few statements
    stmts = []
    # local decls
    for _ in range(r.randint(0, 2)):
        lt = r.choice(["float", "int", "uint", "bool"]) 
        lname = _rand_ident(r, 1, 10)
        if lt == "bool":
            init = r.choice(["true", "false"])
        else:
            init = _rand_number(r)
        stmts.append(f"    {lt} {lname} = {init};")
    # arithmetic or return
    if rtype == "void":
        stmts.append("    // do nothing")
        stmts.append("    return;")
    else:
        if rtype == "bool":
            stmts.append("    return true;")
        else:
            stmts.append(f"    return {_rand_number(r)};")
    return header + " {\n" + "\n".join(stmts) + "\n}\n"

def _rand_includes_and_pragmas(r: random.Random) -> str:
    parts = []
    if r.random() < 0.5:
        # fake include paths; preprocessor may track names only
        incname = _rand_ident(r, 3, 10) + ".fxh"
        parts.append(f"#include \"{incname}\"\n")
    # Some common pragmas or unknown ones
    if r.random() < 0.5:
        parts.append("#pragma message(\"Hello\")\n")
    if r.random() < 0.3:
        parts.append("#ifdef SOME_FLAG\n#define FLAG_VAL 1\n#endif\n")
    return "".join(parts)

def _compose_shader_snippet(r: random.Random) -> str:
    sections: List[str] = []
    # header comments
    if r.random() < 0.7:
        sections.append(_rand_comment(r))
    # includes/pragmas
    sections.append(_rand_includes_and_pragmas(r))
    # a few macro definitions
    for _ in range(r.randint(1, 4)):
        sections.append(_rand_pp_define(r))
    # optional struct
    if r.random() < 0.6:
        sections.append(_rand_typedef_struct(r))
    # variables
    sections.append(_rand_variable_block(r))
    # a function
    sections.append(_rand_function(r))
    text = "\n".join(s for s in sections if s)
    if len(text) > _MAX_LEN:
        text = text[:_MAX_LEN]
    return text

def _compose_identifier_or_filename(r: random.Random) -> str:
    # Provide a plausible filename/path for location::source or include diagnostic
    base = _rand_ident(r, 3, 12)
    if r.random() < 0.5:
        ext = r.choice([".fx", ".fxh", ".hlsl", ".glsl"])
        name = base + ext
    else:
        name = base
    if r.random() < 0.4:
        # add simple subdirectories
        dirs = [ _rand_ident(r, 3, 8) for _ in range(r.randint(1, 3)) ]
        return "/".join(dirs + [name])
    return name

def _compose_string_literal_payload(r: random.Random) -> str:
    # Return a plain text block suitable for string literals or macro replacement
    parts = []
    for _ in range(r.randint(1, 5)):
        parts.append(_rand_plain_text(r, r.randint(3, 30)))
    s = " ".join(parts)
    # Keep length modest
    return s[:256]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a scenario to diversify FUZZ_PARAM_STR consumption sites
    scenario = r.random()
    if scenario < 0.25:
        # Filename-like
        out = _compose_identifier_or_filename(r)
    elif scenario < 0.55:
        # Macro replacement-heavy text line
        lines = []
        for _ in range(r.randint(1, 6)):
            lines.append(_rand_pp_define(r))
        out = "".join(lines)
    elif scenario < 0.8:
        # Shader-like snippet
        out = _compose_shader_snippet(r)
    else:
        # String literal payload or comment-heavy
        if r.random() < 0.5:
            out = _rand_string_literal(r, 200)
        else:
            # mix comments and plain text
            chunks = []
            for _ in range(r.randint(2, 6)):
                if r.random() < 0.5:
                    chunks.append(_rand_comment(r))
                else:
                    chunks.append(_compose_string_literal_payload(r))
            out = "\n".join(chunks)

    if len(out) > _MAX_LEN:
        out = out[:_MAX_LEN]
    return out.encode("utf-8", errors="ignore")
